-- Insert transaction categories
INSERT INTO transaction_categories (transaction_id, category_id, amount)
SELECT 
    t.id,
    c.id,
    t.amount
FROM transactions t
JOIN ynab_categories c ON 
    CASE 
        WHEN t.type = 'Pet Care' THEN c.name = 'Pet Care'
        WHEN t.type = 'House Expenses' THEN c.name = 'House Expenses'
        WHEN t.type = 'HVAC' THEN c.name = 'HVAC'
        WHEN t.type = 'Vacation' THEN c.name = 'Vacation'
        WHEN t.type = 'Groceries' THEN c.name = 'Groceries'
        WHEN t.type = 'Dining Out' THEN c.name = 'Dining Out'
        WHEN t.type = 'Auto Insurance' THEN c.name = 'Auto Insurance'
        WHEN t.type = 'Electric' THEN c.name = 'Electric'
        WHEN t.type = 'Gas' THEN c.name = 'Gas'
        WHEN t.type = 'Water' THEN c.name = 'Water'
    END
WHERE t.user_id = '4fWxBBh9NYhMlwop2SJGt1ZzzI22'
AND c.user_id = '4fWxBBh9NYhMlwop2SJGt1ZzzI22'; 